"use strict";(self.webpackChunkmc_backend_docs=self.webpackChunkmc_backend_docs||[]).push([[8581],{5610:e=>{e.exports=JSON.parse('{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Backend wiki","href":"/MC-Backend-Docs/","docId":"README","unlisted":false},{"type":"link","label":"How the framework works","href":"/MC-Backend-Docs/framework","docId":"framework","unlisted":false},{"type":"link","label":"rules.dsc","href":"/MC-Backend-Docs/rules","docId":"rules","unlisted":false},{"type":"link","label":"Gamerules","href":"/MC-Backend-Docs/gamerules","docId":"gamerules","unlisted":false},{"type":"link","label":"Player flags","href":"/MC-Backend-Docs/flags","docId":"flags","unlisted":false},{"type":"link","label":"Stats","href":"/MC-Backend-Docs/stats","docId":"stats","unlisted":false},{"type":"link","label":"Control effects (world-lock ops and Frontend templates)","href":"/MC-Backend-Docs/control-effects","docId":"control-effects","unlisted":false},{"type":"link","label":"Currencies","href":"/MC-Backend-Docs/currencies","docId":"currencies","unlisted":false},{"type":"link","label":"Analytics","href":"/MC-Backend-Docs/analytics","docId":"analytics","unlisted":false},{"type":"link","label":"Event receipts","href":"/MC-Backend-Docs/receipts","docId":"receipts","unlisted":false},{"type":"link","label":"API engine","href":"/MC-Backend-Docs/api","docId":"api","unlisted":false},{"type":"link","label":"Living entities","href":"/MC-Backend-Docs/living-entities","docId":"living-entities","unlisted":false},{"type":"link","label":"Entities","href":"/MC-Backend-Docs/entities","docId":"entities","unlisted":false},{"type":"link","label":"Mounts","href":"/MC-Backend-Docs/mounts","docId":"mounts","unlisted":false},{"type":"link","label":"Items and Item Skills","href":"/MC-Backend-Docs/items","docId":"items","unlisted":false},{"type":"link","label":"Vaults","href":"/MC-Backend-Docs/vaults","docId":"vaults","unlisted":false},{"type":"link","label":"Trade","href":"/MC-Backend-Docs/trades","docId":"trades","unlisted":false},{"type":"link","label":"In-game player wiki","href":"/MC-Backend-Docs/wiki","docId":"wiki","unlisted":false},{"type":"link","label":"Language","href":"/MC-Backend-Docs/language","docId":"language","unlisted":false},{"type":"link","label":"Loot","href":"/MC-Backend-Docs/loot","docId":"loot","unlisted":false},{"type":"link","label":"SkillMoves, classes, Global Build slots","href":"/MC-Backend-Docs/skills","docId":"skills","unlisted":false},{"type":"link","label":"Cosmetics and gear","href":"/MC-Backend-Docs/cosmetics","docId":"cosmetics","unlisted":false},{"type":"link","label":"Season pass","href":"/MC-Backend-Docs/season-pass","docId":"season-pass","unlisted":false},{"type":"link","label":"Titles / ChatPrefix","href":"/MC-Backend-Docs/titles","docId":"titles","unlisted":false},{"type":"link","label":"Chat","href":"/MC-Backend-Docs/chat","docId":"chat","unlisted":false},{"type":"link","label":"Quests","href":"/MC-Backend-Docs/quests","docId":"quests","unlisted":false},{"type":"link","label":"Travel","href":"/MC-Backend-Docs/travel","docId":"travel","unlisted":false},{"type":"link","label":"Skills, classes, NPCs, menus","href":"/MC-Backend-Docs/content-contracts","docId":"content-contracts","unlisted":false},{"type":"link","label":"Triggerables and Eventstats","href":"/MC-Backend-Docs/triggers","docId":"triggers","unlisted":false},{"type":"link","label":"Menus","href":"/MC-Backend-Docs/menus","docId":"menus","unlisted":false},{"type":"category","label":"HUD","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Layout","href":"/MC-Backend-Docs/hud/layout","docId":"hud/layout","unlisted":false},{"type":"link","label":"Appearance","href":"/MC-Backend-Docs/hud/appearance","docId":"hud/appearance","unlisted":false},{"type":"category","label":"Kinds","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"GLYPH","href":"/MC-Backend-Docs/hud/kinds/glyph","docId":"hud/kinds/glyph","unlisted":false},{"type":"link","label":"BAR","href":"/MC-Backend-Docs/hud/kinds/bar","docId":"hud/kinds/bar","unlisted":false},{"type":"link","label":"STAT","href":"/MC-Backend-Docs/hud/kinds/stat","docId":"hud/kinds/stat","unlisted":false},{"type":"link","label":"TEXT","href":"/MC-Backend-Docs/hud/kinds/text","docId":"hud/kinds/text","unlisted":false},{"type":"link","label":"CURRENCY","href":"/MC-Backend-Docs/hud/kinds/currency","docId":"hud/kinds/currency","unlisted":false},{"type":"link","label":"BOOLEAN","href":"/MC-Backend-Docs/hud/kinds/boolean","docId":"hud/kinds/boolean","unlisted":false},{"type":"link","label":"EFFECT_STRIP","href":"/MC-Backend-Docs/hud/kinds/effect-strip","docId":"hud/kinds/effect-strip","unlisted":false}]},{"type":"category","label":"Operations","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"SHOW_HUD_PART","href":"/MC-Backend-Docs/hud/operations/show-hud-part","docId":"hud/operations/show-hud-part","unlisted":false},{"type":"link","label":"HIDE_HUD_PART","href":"/MC-Backend-Docs/hud/operations/hide-hud-part","docId":"hud/operations/hide-hud-part","unlisted":false},{"type":"link","label":"CLEAR_HUD_PARTS","href":"/MC-Backend-Docs/hud/operations/clear-hud-parts","docId":"hud/operations/clear-hud-parts","unlisted":false},{"type":"link","label":"SET_HUD_LAYOUT","href":"/MC-Backend-Docs/hud/operations/set-hud-layout","docId":"hud/operations/set-hud-layout","unlisted":false}]}],"href":"/MC-Backend-Docs/hud"},{"type":"link","label":"Daily reset","href":"/MC-Backend-Docs/resets","docId":"resets","unlisted":false},{"type":"link","label":"Areas","href":"/MC-Backend-Docs/areas","docId":"areas","unlisted":false},{"type":"category","label":"Mechanics","collapsible":true,"collapsed":true,"customProps":{"description":"Targeting, context, requirements, and operations"},"items":[{"type":"link","label":"Mechanic targeting","href":"/MC-Backend-Docs/mechanics/targeting","docId":"mechanics/targeting","unlisted":false},{"type":"link","label":"Mechanic context","href":"/MC-Backend-Docs/mechanics/context","docId":"mechanics/context","unlisted":false},{"type":"link","label":"Mechanic requirements","href":"/MC-Backend-Docs/mechanics/requirements","docId":"mechanics/requirements","unlisted":false},{"type":"link","label":"Effect operations","href":"/MC-Backend-Docs/mechanics/operations","docId":"mechanics/operations","unlisted":false}],"href":"/MC-Backend-Docs/mechanics/"},{"type":"link","label":"Keeping this wiki honest","href":"/MC-Backend-Docs/maintaining","docId":"maintaining","unlisted":false},{"type":"category","label":"Commands","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"/balance","href":"/MC-Backend-Docs/commands/balance","docId":"commands/balance","unlisted":false},{"type":"link","label":"/withdraw and /redeem","href":"/MC-Backend-Docs/commands/withdraw","docId":"commands/withdraw","unlisted":false},{"type":"link","label":"/pay","href":"/MC-Backend-Docs/commands/pay","docId":"commands/pay","unlisted":false},{"type":"link","label":"/stats","href":"/MC-Backend-Docs/commands/stats","docId":"commands/stats","unlisted":false},{"type":"link","label":"/language","href":"/MC-Backend-Docs/commands/language","docId":"commands/language","unlisted":false},{"type":"link","label":"/packchat","href":"/MC-Backend-Docs/commands/packchat","docId":"commands/packchat","unlisted":false},{"type":"link","label":"/packtitle","href":"/MC-Backend-Docs/commands/packtitle","docId":"commands/packtitle","unlisted":false},{"type":"link","label":"/packwiki","href":"/MC-Backend-Docs/commands/packwiki","docId":"commands/packwiki","unlisted":false},{"type":"link","label":"/packitem","href":"/MC-Backend-Docs/commands/packitem","docId":"commands/packitem","unlisted":false},{"type":"link","label":"/packquest","href":"/MC-Backend-Docs/commands/packquest","docId":"commands/packquest","unlisted":false},{"type":"link","label":"/packwaypoint","href":"/MC-Backend-Docs/commands/packwaypoint","docId":"commands/packwaypoint","unlisted":false},{"type":"link","label":"/packgps","href":"/MC-Backend-Docs/commands/packgps","docId":"commands/packgps","unlisted":false},{"type":"link","label":"/packarea","href":"/MC-Backend-Docs/commands/packarea","docId":"commands/packarea","unlisted":false},{"type":"link","label":"/packentity","href":"/MC-Backend-Docs/commands/packentity","docId":"commands/packentity","unlisted":false},{"type":"link","label":"/packmount","href":"/MC-Backend-Docs/commands/packmount","docId":"commands/packmount","unlisted":false},{"type":"link","label":"/packseasonpass","href":"/MC-Backend-Docs/commands/packseasonpass","docId":"commands/packseasonpass","unlisted":false},{"type":"link","label":"/packreset","href":"/MC-Backend-Docs/commands/packreset","docId":"commands/packreset","unlisted":false},{"type":"link","label":"/staticloot","href":"/MC-Backend-Docs/commands/staticloot","docId":"commands/staticloot","unlisted":false},{"type":"link","label":"/packhologram","href":"/MC-Backend-Docs/commands/packhologram","docId":"commands/packhologram","unlisted":false},{"type":"link","label":"/packprojectile","href":"/MC-Backend-Docs/commands/packprojectile","docId":"commands/packprojectile","unlisted":false},{"type":"link","label":"/packspray","href":"/MC-Backend-Docs/commands/packspray","docId":"commands/packspray","unlisted":false},{"type":"link","label":"/hidecosmetics and /packcosmetic","href":"/MC-Backend-Docs/commands/cosmetics","docId":"commands/cosmetics","unlisted":false},{"type":"link","label":"/packposter","href":"/MC-Backend-Docs/commands/packposter","docId":"commands/packposter","unlisted":false},{"type":"link","label":"/packtrade","href":"/MC-Backend-Docs/commands/packtrade","docId":"commands/packtrade","unlisted":false},{"type":"link","label":"/packvault","href":"/MC-Backend-Docs/commands/packvault","docId":"commands/packvault","unlisted":false},{"type":"link","label":"/packreceipt","href":"/MC-Backend-Docs/commands/packreceipt","docId":"commands/packreceipt","unlisted":false},{"type":"link","label":"/packmongo","href":"/MC-Backend-Docs/commands/packmongo","docId":"commands/packmongo","unlisted":false},{"type":"link","label":"/packapi","href":"/MC-Backend-Docs/commands/packapi","docId":"commands/packapi","unlisted":false}],"href":"/MC-Backend-Docs/commands/"}]},"docs":{"analytics":{"id":"analytics","title":"Analytics","description":"Live for currency and item obtain/spend counters, plus optional shop sink tags.","sidebar":"tutorialSidebar"},"api":{"id":"api","title":"API engine","description":"Live for the staff socket check. pirate-era-api is a shared Python process. Bounty posters are the first feature. Later scripts use the same host, port, and handshake. Host and port are in Backend rules.dsc. The token is not.","sidebar":"tutorialSidebar"},"areas":{"id":"areas","title":"Areas","description":"Live. Area Config templates, world instances, area groups, AreaRule checks, and optional categories.","sidebar":"tutorialSidebar"},"chat":{"id":"chat","title":"Chat","description":"Live as a prefix assembler and a message filter. Harvest: ChatColor.dsc AddChatPrefix stacked champion, yonko, crew, then family name. Chatmonitor.dsc blocked a word list, counted warnings, muted, and rejected a repeat message.","sidebar":"tutorialSidebar"},"commands/balance":{"id":"commands/balance","title":"/balance","description":"Shows the currencies this player actually holds. Any player can run it. Console has no wallet, so it is a player command.","sidebar":"tutorialSidebar"},"commands/cosmetics":{"id":"commands/cosmetics","title":"/hidecosmetics and /packcosmetic","description":"Two cosmetic commands, one file. Hide is for the owner. The pack command is the staff index.","sidebar":"tutorialSidebar"},"commands/index":{"id":"commands/index","title":"Commands","description":"Every Backend type: command script lives in its own file. Related commands for one system share a file. Engine tasks stay in the system file. A task moves with the command only when that command is the only caller.","sidebar":"tutorialSidebar"},"commands/language":{"id":"commands/language","title":"/language","description":"Cycles the language this player reads. Any player can run it. Console stops.","sidebar":"tutorialSidebar"},"commands/packapi":{"id":"commands/packapi","title":"/packapi","description":"Pings the engine API. Op or console.","sidebar":"tutorialSidebar"},"commands/packarea":{"id":"commands/packarea","title":"/packarea","description":"Places and edits world areas from where you stand. Op only, and the sender must be a player. Console stops.","sidebar":"tutorialSidebar"},"commands/packchat":{"id":"commands/packchat","title":"/packchat","description":"Shows the chat line this player would send, including prefix and suffix. It does not broadcast, and it does not run the word filter. Any player can run it. Console stops.","sidebar":"tutorialSidebar"},"commands/packentity":{"id":"commands/packentity","title":"/packentity","description":"Staff tool for indexed combat mobs. Ops and the console can run it. Spawn, radius prune, and smoke need a player.","sidebar":"tutorialSidebar"},"commands/packgps":{"id":"commands/packgps","title":"/packgps","description":"Staff tool for the GPS arrow index. Ops and the console can run it.","sidebar":"tutorialSidebar"},"commands/packhologram":{"id":"commands/packhologram","title":"/packhologram","description":"Places, lists, or removes persistent world holograms. Op only, and the sender must be a player. Console stops.","sidebar":"tutorialSidebar"},"commands/packitem":{"id":"commands/packitem","title":"/packitem","description":"Gives a pack Item Config to a player. Ops and the console can run it. A linked player must be op.","sidebar":"tutorialSidebar"},"commands/packmongo":{"id":"commands/packmongo","title":"/packmongo","description":"Pings the engine Mongo connection. Op or console. This is not player flag save.","sidebar":"tutorialSidebar"},"commands/packmount":{"id":"commands/packmount","title":"/packmount","description":"Summons, puts away, or lists a player\'s saved mount rows. Ops and the console can run it. A missing player is the sender. Console must name a player.","sidebar":"tutorialSidebar"},"commands/packposter":{"id":"commands/packposter","title":"/packposter","description":"Places, refreshes, lists, and clears bounty poster frames. Op only. Place, remove, and list need a player.","sidebar":"tutorialSidebar"},"commands/packprojectile":{"id":"commands/packprojectile","title":"/packprojectile","description":"Lists or clears tracked projectile shots. Ops and the console can run it.","sidebar":"tutorialSidebar"},"commands/packquest":{"id":"commands/packquest","title":"/packquest","description":"Reads or edits quest progress stored on flag_saves.quests. This is chat, not a menu.","sidebar":"tutorialSidebar"},"commands/packreceipt":{"id":"commands/packreceipt","title":"/packreceipt","description":"Opens Mongo receipt rows, or inserts a dummy row so you can prove the collection without two players trading. Op only. The list menu needs a player.","sidebar":"tutorialSidebar"},"commands/packreset":{"id":"commands/packreset","title":"/packreset","description":"Lists or fires Frontend dailyreset_ rows. Op only. due, run, and test need a player. Console can list.","sidebar":"tutorialSidebar"},"commands/packseasonpass":{"id":"commands/packseasonpass","title":"/packseasonpass","description":"Opens the season pass, or edits a player\'s progress. open and scroll are any player. xp, track, redeem, and wipe are op. Console can run the edit actions when a player is named. Opening the menu needs a player.","sidebar":"tutorialSidebar"},"commands/packspray":{"id":"commands/packspray","title":"/packspray","description":"Lists or clears tracked spray frames. Ops and the console can run it.","sidebar":"tutorialSidebar"},"commands/packtitle":{"id":"commands/packtitle","title":"/packtitle","description":"Opens the title equip menu for you. Any player can run it. Console stops.","sidebar":"tutorialSidebar"},"commands/packtrade":{"id":"commands/packtrade","title":"/packtrade","description":"Lists or clears live trade sessions. Op only. list needs a player. Console can clear, prune, and remove.","sidebar":"tutorialSidebar"},"commands/packvault":{"id":"commands/packvault","title":"/packvault","description":"Lists or clears shared vault notes. Op only. list needs a player. Console can clear, prune, and remove.","sidebar":"tutorialSidebar"},"commands/packwaypoint":{"id":"commands/packwaypoint","title":"/packwaypoint","description":"Places waypoints and travels to them. go is any player. set, move, remove, list, show, here, force, clear, and prune are op. Console can list, remove, clear, and prune.","sidebar":"tutorialSidebar"},"commands/packwiki":{"id":"commands/packwiki","title":"/packwiki","description":"Opens the in-game wiki for you. Any player can run it. This is the player wiki, not this docs site.","sidebar":"tutorialSidebar"},"commands/pay":{"id":"commands/pay","title":"/pay","description":"Sends wallet currency from you to another online player. The command always exists. Whether it moves money depends on the pack.","sidebar":"tutorialSidebar"},"commands/staticloot":{"id":"commands/staticloot","title":"/staticloot","description":"Binds a loottable_* to the trapped chest or barrel you are looking at. Op only. list needs a player. Bind and unbind need you to look at the block.","sidebar":"tutorialSidebar"},"commands/stats":{"id":"commands/stats","title":"/stats","description":"Prints this player\'s effective stat levels. Any player can run it.","sidebar":"tutorialSidebar"},"commands/withdraw":{"id":"commands/withdraw","title":"/withdraw and /redeem","description":"/withdraw turns wallet currency into one coin item. /redeem turns that coin item back into the wallet. Both are player commands. They share Currencies/currencywithdraw.dsc.","sidebar":"tutorialSidebar"},"content-contracts":{"id":"content-contracts","title":"Skills, classes, NPCs, menus","description":"SkillMoves, classes, and Global Build slots: skills.md. This page keeps prefixes that still have no engine.","sidebar":"tutorialSidebar"},"control-effects":{"id":"control-effects","title":"Control effects (world-lock ops and Frontend templates)","description":"Live. World locks are mechanic operations, same as PLAYSOUND. type: NOWALK runs a Backend task that zeros walk. It does not SET_STAT a matching stat id.","sidebar":"tutorialSidebar"},"cosmetics":{"id":"cosmetics","title":"Cosmetics and gear","description":"Live. Gear is items. Cosmetics are stands. Frontend may run both on one click. Backend does not spawn a stand because a gear id was set.","sidebar":"tutorialSidebar"},"currencies":{"id":"currencies","title":"Currencies","description":"Live. Frontend currency_* scripts are the registry. The engine does not pick a default currency.","sidebar":"tutorialSidebar"},"entities":{"id":"entities","title":"Entities","description":"Combat mobs and companions. Prefixes: entity, entityai, entityanimation, entitymodel, entityskill, entityprofile. Living HP and damage stay on livingentity. On the Frontend, one mob\'s entity, entityai, and entityskill containers share that mob\'s file (entityexampleboar.dsc). Profiles and living entities stay shared. See living-entities.md and content-contracts.md.","sidebar":"tutorialSidebar"},"flags":{"id":"flags","title":"Player flags","description":"Partial. Paths come from rules.dsc flag_saves. Getters and setters exist for stats, currencies, living-entity bind, language, triggerable bind, casting session, trigger cooldowns, SkillMove category bans, gear slot ids, cosmetic persist channels, season pass counters, vault slot maps, daily reset period stamps, and quest progress.","sidebar":"tutorialSidebar"},"framework":{"id":"framework","title":"How the framework works","description":"Live. Backend is the engine (tasks, procs, world events). Frontend is type: data configs. They share vocabulary through rules.dsc.","sidebar":"tutorialSidebar"},"gamerules":{"id":"gamerules","title":"Gamerules","description":"Live as pack-wide server policy. Frontend script registry_gamerules (rules.dsc pointer gamerules). Nested maps only.","sidebar":"tutorialSidebar"},"hud/appearance":{"id":"hud/appearance","title":"Appearance","description":"Pack fonts have long ids such as pehudscaledfontpack hp.","sidebar":"tutorialSidebar"},"hud/kinds/bar":{"id":"hud/kinds/bar","title":"BAR","description":"A bar turns a consumable stat into one letter from the empty-to-full alphabet. Current and max come from that stat. The letter is the fill.","sidebar":"tutorialSidebar"},"hud/kinds/boolean":{"id":"hud/kinds/boolean","title":"BOOLEAN","description":"A boolean part watches a pack stat. On draws onglyph. Off draws offglyph.","sidebar":"tutorialSidebar"},"hud/kinds/currency":{"id":"hud/kinds/currency","title":"CURRENCY","description":"A currency part prints a wallet amount. Large amounts use the short suffixes from appearance: k, m, b, and t.","sidebar":"tutorialSidebar"},"hud/kinds/effect-strip":{"id":"hud/kinds/effect-strip","title":"EFFECT_STRIP","description":"An effect strip is a fixed row of slots. You list every slot. Unused slots still draw, so the row keeps its width.","sidebar":"tutorialSidebar"},"hud/kinds/glyph":{"id":"hud/kinds/glyph","title":"GLYPH","description":"A glyph is one pack letter. Use it for the hotbar anchor, an outline, or a full-screen frame.","sidebar":"tutorialSidebar"},"hud/kinds/stat":{"id":"hud/kinds/stat","title":"STAT","description":"A stat part prints a number from a pack stat: the current value, the max, or both.","sidebar":"tutorialSidebar"},"hud/kinds/text":{"id":"hud/kinds/text","title":"TEXT","description":"A text part prints a transcript key or a literal string.","sidebar":"tutorialSidebar"},"hud/layout":{"id":"hud/layout","title":"Layout","description":"A layout is the arrangement the player is looking at. The player has one active layout. Another hud script stays off until SETHUD_LAYOUT replaces it. Both rows are never drawn together. Write one when that arrangement is reusable, such as the normal combat bar or a smaller bar for a cutscene. A temporary icon on the same bar is a show operation, not a second layout. Minecraft centers the whole bar, so the first slot is the pin (the hotbar letter in this pack). Every later slot is a distance from that pin.","sidebar":"tutorialSidebar"},"hud/operations/clear-hud-parts":{"id":"hud/operations/clear-hud-parts","title":"CLEAR_HUD_PARTS","description":"CLEARHUDPARTS belongs in a mechanic operations: map. A skill move uses the same map. It drops show and hide overlays. The layout script stays as it is.","sidebar":"tutorialSidebar"},"hud/operations/hide-hud-part":{"id":"hud/operations/hide-hud-part","title":"HIDE_HUD_PART","description":"HIDEHUDPART belongs in a mechanic operations: map. A skill move uses the same map. The hide forces that layout slot to draw its pad, so later offsets stay put.","sidebar":"tutorialSidebar"},"hud/operations/set-hud-layout":{"id":"hud/operations/set-hud-layout","title":"SET_HUD_LAYOUT","description":"SETHUDLAYOUT belongs in a mechanic operations: map. A skill move uses the same map. It replaces the player\'s one active layout with another hud_ script and keeps that choice. The bar is one string from that row, so the previous layout stops drawing.","sidebar":"tutorialSidebar"},"hud/operations/show-hud-part":{"id":"hud/operations/show-hud-part","title":"SHOW_HUD_PART","description":"SHOWHUDPART belongs in a mechanic operations: map. A skill move, an item skill, a triggerable, or RUN_MECHANIC all run that map. The same mechanic can show a part and play a sound as two numbered entries.","sidebar":"tutorialSidebar"},"hud/README":{"id":"hud/README","title":"HUD","description":"The HUD is the text bar above the hotbar. A layout is one arrangement of pieces for a way of playing. Combat shows health, stamina, and belly. A quieter layout shows health only. The player has one active layout. SETHUDLAYOUT replaces it, and both rows are never on the bar together. A part is one piece. Appearance is the shared nickname list so a part can say font keep a blank of the same width, or leave the piece out.","sidebar":"tutorialSidebar"},"items":{"id":"items","title":"Items and Item Skills","description":"Partial. Create/give stamps display plus itemscript / level (and optional tier / set flags). Item Skills are itemskill* envelopes loaded by RUNITEMSKILL. Eat is Item Config consume: plus ONCONSUME. World click is a Frontend triggerable, same idea as SkillMove on hotbar. RepairProfile / LevelProfile YAML is still Contract. Spend itself is APPLY_TRANSACTION. Worn set-piece counting is not an engine.","sidebar":"tutorialSidebar"},"language":{"id":"language","title":"Language","description":"Live. Transcript scripts use prefix generaltranscript. Example: pirate-era-core-frontend/language/englishtranscript.dsc. Add generaltranscriptspanish (same keys) for a second language. Missing keys fall back to registrygamerules.language.default.","sidebar":"tutorialSidebar"},"living-entities":{"id":"living-entities","title":"Living entities","description":"Partial. Player bind and stat init work. Damage routing (APPLY / REDIRECT / SPLIT, conditions, OnSuccess / OnDeplete / OnFail) is Live. deal_damage is Live. Combat and resistance profiles use Vanilla Adjustifier FLAT + - * / on the vanilla intercept.","sidebar":"tutorialSidebar"},"loot":{"id":"loot","title":"Loot","description":"Partial / Live resolver. Prefixes loottable, lootpool, lootentry, lootcrate. Backend rolls those scripts and grants through grantlootresults. Party split is not in this engine.","sidebar":"tutorialSidebar"},"maintaining":{"id":"maintaining","title":"Keeping this wiki honest","description":"Update docs/ in the same change as the engine or rules.dsc. This folder is the option list. The architecture plan is the roadmap. Do not let them drift.","sidebar":"tutorialSidebar"},"mechanics/context":{"id":"mechanics/context","title":"Mechanic context","description":"Live. Keys are rules.dsc mechaniccontext. Build with buildmechaniccontext. Read with getmechanic_*. Do not hardcode field names.","sidebar":"tutorialSidebar"},"mechanics/operations":{"id":"mechanics/operations","title":"Effect operations","description":"Dispatcher: handlemechanicoperations in Mechanics/Core/mechanicutils.dsc. Each operations..type is a case. New ops get a file under Mechanics/Individualoperations/ and a case here.","sidebar":"tutorialSidebar"},"mechanics/README":{"id":"mechanics/README","title":"Mechanics","description":"Partial. Dispatcher, context, targeting, requirements, inherit, PLAYSOUND, PLAYEFFECT, APPLYVELOCITY, PROJECTILE, DASH, SPAWNNOTABLE, SPAWNHOLOGRAM, STARTGPS, STOPGPS, SHOWHUDPART, HIDEHUDPART, CLEARHUDPARTS, SETHUDLAYOUT, PLACESPRAY, OPENSPRAYMENU, OPENTITLEMENU, EQUIPTITLE, UNEQUIPTITLE, CLEARTITLES, OPENWIKIMENU, REVEALWIKILORE, EQUIPGEAR, CLEARGEAR, EQUIPCOSMETIC, CLEARCOSMETIC, SPAWNCOSMETIC, NARRATE, GIVEITEM, GRANTLOOT, STARTQUEST, ADVANCEQUEST, COMPLETEQUEST, GRANTSEASONXP, SETSEASONTRACK, REDEEMSEASONREWARD, OPENSEASONPASS, APPLYTRANSACTION, OPENLOOTCRATE, TELEPORT, TRAVELTOWAYPOINT, ITEMCOOLDOWN, SWING, DEALDAMAGE, world-lock ops (NOWALK, \u2026), MODIFYSTAT, MODIFYSTATLEVEL, OVERLAYSTATLEVEL, CLEARSTATOVERLAY, SETSTAT, TOGGLESTAT, RUNSKILLMOVE, RUNITEMSKILL, RUNMECHANIC, CASTVANILLAEFFECT, BANCATEGORY, OPENMENU, CLOSEMENU, OPENCONFIRM, OPENDIALOGUE, OPENTYPING, OPENSTORAGE, and OPEN_TRADE are Live. Other ops are missing.","sidebar":"tutorialSidebar"},"mechanics/requirements":{"id":"mechanics/requirements","title":"Mechanic requirements","description":"Live. Missing or empty requirements always pass. Unknown type values fail.","sidebar":"tutorialSidebar"},"mechanics/targeting":{"id":"mechanics/targeting","title":"Mechanic targeting","description":"Every effect-operation calls resolvemechanicoperationtargets. PLAYSOUND and MODIFYSTAT smoke: pirate-era-core-frontend/Mechanics/mechanicexamples.dsc.","sidebar":"tutorialSidebar"},"menus":{"id":"menus","title":"Menus","description":"Live for open, click, close, footer fakeitems, packet cancel, kinds, OPENMENU, CLOSEMENU, OPENCONFIRM, OPENDIALOGUE, and OPEN_TYPING.","sidebar":"tutorialSidebar"},"mounts":{"id":"mounts","title":"Mounts","description":"Live for the mount ops and the sit, quit, death, and reload save hooks. Mounts/ and the SUMMONMOUNT through SETMOUNTROW tasks read these keys. Area rule MOUNTSPEED_CAP is registered. none means no scale.","sidebar":"tutorialSidebar"},"quests":{"id":"quests","title":"Quests","description":"Live. Categories, quests, objective progress, complete mechanics, and loot entry rewards.","sidebar":"tutorialSidebar"},"README":{"id":"README","title":"Backend wiki","description":"Option catalog for the Denizen MMORPG backend (mc-denizen-core-backend). Frontend content lives in pirate-era-core-frontend. This folder is the living list of what the engine accepts. Host these .md files as a wiki later without rewriting them.","sidebar":"tutorialSidebar"},"receipts":{"id":"receipts","title":"Event receipts","description":"Live for TRADE inserts and staff /packreceipt. TRANSACTION is reserved for shops. Analytics counters stay numbers only. See analytics.md.","sidebar":"tutorialSidebar"},"resets":{"id":"resets","title":"Daily reset","description":"Live as one Backend scheduler plus Frontend dailyreset rows. Harvest00, wiped dailyreward, announced, wiped monthly pass, reset hourly replay, and granted login gifts.","sidebar":"tutorialSidebar"},"rules":{"id":"rules","title":"rules.dsc","description":"Live as the shared contract. File: rules.dsc. Read it with proc[getrulevalue].context[]. Never copy these strings into ops.","sidebar":"tutorialSidebar"},"season-pass":{"id":"season-pass","title":"Season pass","description":"Live. One Frontend seasonpass_ file per season. Backend stores counters and redeems through existing ops. XP sources are triggerables. The menu is PAGE or SCROLL.","sidebar":"tutorialSidebar"},"skills":{"id":"skills","title":"SkillMoves, classes, Global Build slots","description":"Partial. Cast is still RUNSKILLMOVE plus Frontend kind: REFERENCE slots. The envelope is categories, requirements, and Cost Component costs. There is no class engine and no second Backend cast runtime. Do not bind mechanic ids on stat_skillmove_.","sidebar":"tutorialSidebar"},"stats":{"id":"stats","title":"Stats","description":"Live for value, regen, consumable, affects, linear equation. Partial for combat-state regen (PAUSE/SLOWED), percent-loss on death, extra equations.","sidebar":"tutorialSidebar"},"titles":{"id":"titles","title":"Titles / ChatPrefix","description":"Live as a catalog, ordered persist lists, and chat paint. Word filter and crew/rank rows are not this page.","sidebar":"tutorialSidebar"},"trades":{"id":"trades","title":"Trade","description":"Live. Shared 54 chest, ready handshake, swap, cancel return. Not a gui: true wiki PAGE. Convert-money in legacy TradeSystem.dsc is already Cost Component (/withdraw). Counts stay analytics. Who/what/when is Mongo record_receipt TRADE. YAML /Trades/ is forbidden. See receipts.md and analytics.md.","sidebar":"tutorialSidebar"},"travel":{"id":"travel","title":"Travel","description":"Live. Waypoint Config plus TRAVELTOWAYPOINT. Paying uses Cost Component. Requirements use the same maps as mechanics.","sidebar":"tutorialSidebar"},"triggers":{"id":"triggers","title":"Triggerables and Eventstats","description":"Partial. Player-bound triggerable configs init on join. World events dispatch through fire_stat_event. Eventstat is a stat with stateventconfig. A SkillMove is a skillmove data script with mechanics. An Item Skill is an itemskill data script listed on an Item Config. Hotbar 1 with casting mode runs RUNSKILLMOVE on statskillmove_1.","sidebar":"tutorialSidebar"},"vaults":{"id":"vaults","title":"Vaults","description":"Live. Private pages persist on flagsaves.vaults. Shared banks are Denizen noted inventories plus vaultindex. Not gui: true info menus. Not a crew engine.","sidebar":"tutorialSidebar"},"wiki":{"id":"wiki","title":"In-game player wiki","description":"Live. Hub plus category PAGE menus. Backend indexes existing prefixes and builds lore on click. This is not docs/ (dev option catalog) and not a Discord or web wiki. There is no wiki_ runtime prefix.","sidebar":"tutorialSidebar"}}}')}}]);